import { Direction, MoveToResult, PathBlockedStrategy } from "grid-engine";
import { GameScene } from "../GameScene";
import { CharacterConfig } from "type";

export class Character {
  protected scene: GameScene;
  spriteId: string;
  sprite: Phaser.GameObjects.Sprite;

  constructor(scene: GameScene, config: CharacterConfig) {
    this.scene = scene;
    this.spriteId = config.sprite;
    this.sprite = this.scene.add.sprite(0, 0, config.sprite);
  }

  moveTo = (x: number, y: number, onEnd?: (result?: MoveToResult) => void) => {
    this.scene.gridEngine
      .moveTo(
        this.spriteId,
        { x, y },
        {
          pathBlockedStrategy: PathBlockedStrategy.STOP,
          algorithm: 'JPS'
        },
      )
      .forEach(({ charId, result }) => {
        if (charId === this.spriteId && onEnd) {
          onEnd(result);
        }
      });
  };

  moveDirection = (direction: Direction) => {
    this.scene.gridEngine.move(this.spriteId, direction);
  };

  moveStop = () => {
    this.scene.gridEngine.stopMovement(this.spriteId);
  };
}
